#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  char name[32];  int    nCode;  } Queue_Grup;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressGrup(DefinePress)  {  if ( nCode == 0 )    return 0;  //  if ( nCode == 1 )    return 0;  //  Queue_Grup* p = (Queue_Grup*)s;  if ( *p->name == '.'  ) return 1;  //  if ( point.x == -1 && point.y == -1 )    {    if ( ( p->nCode & 0xff ) != nCode )      return 1;    }  else  if ( !::PtInRect( &p->mRect, point ) )    return 0;  //  static char szGoto[256];  lstrcpy( szGoto, p->name );  ::PostMsg( q.hWnd, p->btSendType, (LPARAM)szGoto );  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintGrup(DefinePaint)  {  QueueP(Queue_Grup);  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddGrup(DefineTegs)  {  AddQueueEx(Queue_Grup);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_GROUP;  // Определение функции вывода  p->paint = &PaintGrup;  p->press = &PressGrup;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    { 'I', "code", &p->nCode },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  StrCPY( p->name, teg[0].value, sizeof(p->name) );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~